<?php
namespace App\Features\Post\Services;
use App\Features\Post\Models\Post;use App\Models\User;use PhpOffice\PhpSpreadsheet\Spreadsheet;use PhpOffice\PhpSpreadsheet\Writer\Xlsx;use PhpOffice\PhpSpreadsheet\IOFactory;use Symfony\Component\HttpFoundation\StreamedResponse;use Illuminate\Support\Str;
class PostExcelService {public function export($query,string $filename='blogverse-posts.xlsx'):StreamedResponse{$rows=$query->with('user')->get();$sheet=(new Spreadsheet())->getActiveSheet();$sheet->fromArray(['ID','Penulis','Judul','Slug','Kategori','Ringkasan','Konten','Status','Diterbitkan','Dibuat'],null,'A1');foreach($rows as $i=>$post)$sheet->fromArray([$post->id,$post->user?->name,$post->title,$post->slug,$post->category,$post->excerpt,$post->content,$post->is_published?'Published':'Draft',$post->published_at?->format('Y-m-d H:i:s'),$post->created_at?->format('Y-m-d H:i:s')],null,'A'.($i+2));foreach(range('A','J') as $col)$sheet->getColumnDimension($col)->setAutoSize(true);return response()->streamDownload(function()use($rows,$sheet){(new Xlsx($sheet->getParent()))->save('php://output');},$filename);}public function import(string $path,User $user):int{$sheet=IOFactory::load($path)->getActiveSheet();$rows=$sheet->toArray();$count=0;foreach(array_slice($rows,1) as $row){if(empty($row[2])||empty($row[6]))continue;$published=strtolower((string)($row[7]??''))==='published';$user->posts()->create(['title'=>Str::limit((string)$row[2],250,''),'slug'=>Post::uniqueSlug((string)$row[2]),'category'=>in_array($row[4]??'',array_map(fn($category)=>$category->value,\App\Features\Post\Enums\PostCategory::cases()))?$row[4]:'Umum','excerpt'=>$row[5]?:Str::limit(strip_tags($row[6]),180),'content'=>$row[6],'is_published'=>$published,'published_at'=>$published?now():null]);$count++;}return $count;}}
